    'zx.in.lead':'无需签证、无需机票，通过智能手机即可与日本持牌医生进行一对一中文问诊。日本医生以严谨、细致的诊疗态度著称，每次问诊均有完整病历记录，让您享有媲美亲临日本的医疗体验。',
    'zx.in.p1':'我们的在线问诊平台由日本厚生劳动省认可的持牌医疗机构运营，所有参与问诊的医生均持有日本医师执照，在各专科领域具备丰富临床经验，为您提供专业、负责任的医疗意见。',
    'zx.in.p2':'问诊后，医生可直接在线开具处方，由日本持牌药局将药品国际邮寄至您的住所。全程中文服务，无语言壁垒，医疗记录完整留存，方便后续复诊追踪。',
    'zx.in.hb.t':'🌸 樱医线上问诊承诺',
    'zx.in.hb.p':'所有问诊医生100%持有日本医师执照，平台由日本厚生劳动省认可机构运营，处方药品通过合规渠道国际配送，保障您的用药安全与合法性。',
    'zx.sp.1.p':'高血压、糖尿病、高血脂等慢性病管理，感冒发烧等常见病症诊治，用药指导与复诊随访，无需多次往返医院。',
    'zx.sp.1.tags':'<span class="item-tag">慢性病管理</span><span class="item-tag">用药指导</span><span class="item-tag">健康咨询</span><span class="item-tag">复诊随访</span>',
    'zx.sp.2.p':'过敏性鼻炎、慢性鼻窦炎、咽喉炎等常见耳鼻喉问题在线诊治，处方开具直送到家，告别反复排队困扰。',
    'zx.sp.2.tags':'<span class="item-tag">过敏性鼻炎</span><span class="item-tag">鼻窦炎</span><span class="item-tag">咽喉炎</span><span class="item-tag">耳部问题</span>',
    'zx.sp.3.p':'痤疮、湿疹、荨麻疹、色斑等皮肤问题专科诊治，配合日本高品质皮肤科用药，改善各类肌肤困扰。',
    'zx.sp.3.tags':'<span class="item-tag">痤疮治疗</span><span class="item-tag">湿疹过敏</span><span class="item-tag">色斑管理</span><span class="item-tag">美容皮肤</span>',
    'zx.sp.4.p':'儿童常见病症在线问诊，日本儿科专科医生为宝宝健康保驾护航，安全用药建议，让父母安心放心。',
    'zx.sp.4.tags':'<span class="item-tag">儿童常见病</span><span class="item-tag">发育咨询</span><span class="item-tag">安全用药</span><span class="item-tag">健康评估</span>',
    'zx.sp.5.p':'雄性激素型脱发（AGA）专科在线诊治，日本持牌医生开具非那雄胺、米诺地尔等处方药，直送到家，告别脱发困扰。',
    'zx.sp.5.tags':'<span class="item-tag">AGA脱发</span><span class="item-tag">处方用药</span><span class="item-tag">男女均适</span><span class="item-tag">持续随访</span>',
    'zx.sp.6.p':'日本专科医生科学制定个性化减重方案，配合食欲抑制处方药（如GLP-1类药物），安全有效实现健康体重管理。',
    'zx.sp.6.tags':'<span class="item-tag">科学减重</span><span class="item-tag">GLP-1处方</span><span class="item-tag">饮食指导</span><span class="item-tag">持续追踪</span>',
    'zx.adv.1.p':'所有参与问诊的医生均持有日本医師免許（医师执照），在各科领域具备扎实的临床培训背景，提供专业、负责的医疗建议。',
    'zx.adv.2.p':'全程中文问诊，告别语言壁垒。无需担心用日语描述症状的困难，医生直接用中文与您沟通，确保诊断信息准确传达。',
    'zx.adv.3.p':'问诊后医生可直接开具电子处方，由日本持牌药局通过合规渠道将药品国际邮寄至全球主要地区，让您在家即可获得日本原装药品。',
    'zx.adv.4.p':'在线预约后按时开始问诊，无需在医院走廊漫长等候。灵活安排问诊时间，完全适配您的工作与生活节奏。',
    'zx.adv.5.p':'每次问诊均生成完整电子病历，方便后续复诊追踪，也可作为转介其他医生或机构的参考依据。',
    'zx.adv.6.p':'一对一私密问诊空间，严格遵守个人信息保护法，所有健康数据安全加密存储，让您可以坦然分享敏感健康问题。',
    'zx.ps.1.p':'填写基本健康信息，完成身份验证，全程仅需5分钟',
    'zx.ps.2.p':'根据症状选择对应专科，浏览医生资料，预约合适时段',
    'zx.ps.3.p':'视频或文字问诊，全程中文沟通，详细描述症状获取专业诊断',
    'zx.ps.4.p':'医生在线开具电子处方，提供详细用药说明与复诊建议',
    'zx.ps.5.p':'日本原装药品由持牌药局直接国际邮寄，安全合规送达您手中',
    'zx.who.1.p':'在日旅游或出差期间突发不适，无需辗转寻找医院，手机即可获得日本医生诊治',
    'zx.who.2.p':'身处海外但信任日本医疗品质，需要日本专科医生建议或日本原装处方药',
    'zx.who.3.p':'工作繁忙无暇前往医院，希望在家中或办公室随时享用便捷医疗服务',
    'zx.who.4.p':'需要持续管理慢性病或长期服药者，通过线上复诊轻松获取续药处方',
    'zx.faq.1.a':'是的，所有参与问诊的医生均持有日本厚生劳动省颁发的医師免許（医师执照），并在各自专科领域具备完整的临床培训背景。平台由日本合规医疗机构运营，受日本医疗法规监管，您可在问诊前查阅医生的执照信息。',
    'zx.faq.2.a':'目前支持配送至中国大陆、香港、台湾、新加坡、马来西亚、澳大利亚等主要华人聚居地区及多个国际目的地。具体可配送的药品种类因目的地的药品进口法规而异，我们会在问诊时为您说明。请注意，部分管制药品可能无法国际邮寄，届时医生会提供替代方案。',
    'zx.faq.3.a':'初诊费用因科室和问诊时长而有所不同，一般在300–800元人民币区间。处方药品费用及配送费用另计，均会在问诊前透明告知。首次通过樱医预约可享专属优惠，详情请联系我们的顾问获取报价。',
    'zx.faq.4.a':'线上问诊适合慢性病管理、常见病症咨询、复诊续药、AGA脱发、减重管理、皮肤问题等非紧急医疗需求。如遇急症（如剧烈胸痛、呼吸困难、严重外伤等）或需要体格检查、手术的情况，请及时前往当地医院急诊。医生在问诊中也会根据您的情况判断是否需要转诊。',
    'zx.faq.5.a':'支持中文（普通话/广东话）、日语、英语三种语言问诊。绝大多数患者使用中文即可与医生直接流畅沟通，无需翻译。所有问诊记录、处方说明及用药指导均可提供中文版本。',
