    'zx.s3.num':'3 Lang','zx.s4.num':'Global',
    'zx.in.lead':'No visa or flights needed. Consult one-on-one with a licensed Japanese doctor in Chinese via your smartphone. Japanese doctors are known for their meticulous approach — every consultation includes a full medical record, giving you an experience that rivals visiting Japan in person.',
    'zx.in.p1':'Our online consultation platform is operated by a licensed medical institution approved by Japan\'s Ministry of Health, Labour and Welfare. All participating doctors hold a Japanese medical licence with extensive clinical experience in their specialties, providing professional and responsible medical advice.',
    'zx.in.p2':'After your consultation, doctors can issue electronic prescriptions directly, with medications mailed internationally from a licensed Japanese pharmacy to your home. Full Chinese-language service — no language barriers, complete medical records retained, easy follow-up tracking.',
    'zx.in.hb.t':'🌸 Sakura Medical Online Consultation Pledge',
    'zx.in.hb.p':'100% of our consultation doctors hold a Japanese medical licence. The platform is operated by a Ministry of Health-approved institution. Prescriptions are delivered internationally through compliant channels, ensuring the safety and legality of your medications.',
    'zx.sp.1.p':'Management of chronic conditions such as hypertension, diabetes, and high cholesterol; treatment of common illnesses; medication guidance and follow-up visits — all without repeated hospital trips.',
    'zx.sp.1.tags':'<span class="item-tag">Chronic Disease</span><span class="item-tag">Medication Guidance</span><span class="item-tag">Health Consult</span><span class="item-tag">Follow-up</span>',
    'zx.sp.2.p':'Online treatment for common ENT conditions including allergic rhinitis, chronic sinusitis, and pharyngitis. Prescriptions issued and delivered directly to your door — no more long queues.',
    'zx.sp.2.tags':'<span class="item-tag">Allergic Rhinitis</span><span class="item-tag">Sinusitis</span><span class="item-tag">Pharyngitis</span><span class="item-tag">Ear Problems</span>',
    'zx.sp.3.p':'Specialist care for acne, eczema, urticaria, pigmentation, and other skin concerns, combined with high-quality Japanese dermatological medications to address a wide range of skin issues.',
    'zx.sp.3.tags':'<span class="item-tag">Acne Treatment</span><span class="item-tag">Eczema & Allergy</span><span class="item-tag">Pigmentation</span><span class="item-tag">Cosmetic Skin</span>',
    'zx.sp.4.p':'Online consultations for common childhood illnesses. Japan\'s paediatric specialists safeguard your child\'s health with safe medication advice, giving parents peace of mind.',
    'zx.sp.4.tags':'<span class="item-tag">Common Illness</span><span class="item-tag">Development</span><span class="item-tag">Safe Medication</span><span class="item-tag">Health Assessment</span>',
    'zx.sp.5.p':'Specialist online treatment for androgenetic alopecia (AGA). Licensed Japanese doctors prescribe finasteride, minoxidil, and other medications — delivered directly to your door.',
    'zx.sp.5.tags':'<span class="item-tag">AGA Hair Loss</span><span class="item-tag">Prescription</span><span class="item-tag">Men & Women</span><span class="item-tag">Ongoing Follow-up</span>',
    'zx.sp.6.p':'Japan\'s specialist doctors design personalised weight management plans, combined with appetite-suppressant prescriptions (such as GLP-1 medications) for safe and effective weight management.',
    'zx.sp.6.tags':'<span class="item-tag">Weight Loss</span><span class="item-tag">GLP-1 Prescription</span><span class="item-tag">Diet Guidance</span><span class="item-tag">Progress Tracking</span>',
    'zx.adv.1.p':'All participating doctors hold a Japanese 医師免許 (medical licence) and have strong clinical training backgrounds in their respective fields, providing professional and responsible medical advice.',
    'zx.adv.2.p':'Consult entirely in Chinese — no language barriers. No need to describe symptoms in Japanese. The doctor communicates directly in Chinese, ensuring accurate diagnosis.',
    'zx.adv.3.p':'After consultation, doctors issue electronic prescriptions online. Licensed Japanese pharmacies ship medications internationally to major regions worldwide via compliant channels — authentic Japanese medications delivered home.',
    'zx.adv.4.p':'Schedule your consultation online and start on time — no waiting in hospital corridors. Flexible booking that fits your work and lifestyle.',
    'zx.adv.5.p':'Every consultation generates a complete electronic medical record for easy follow-up tracking, which can also serve as a reference for referrals to other doctors or institutions.',
    'zx.adv.6.p':'Private one-on-one consultation space, strictly compliant with personal data protection laws. All health data is securely encrypted, allowing you to openly discuss sensitive health matters.',
    'zx.ps.1.p':'Enter basic health information and complete identity verification — takes just 5 minutes',
    'zx.ps.2.p':'Choose the appropriate specialty based on your symptoms, browse doctor profiles, and book a time slot',
    'zx.ps.3.p':'Video or text consultation, entirely in Chinese — describe your symptoms in detail for a professional diagnosis',
    'zx.ps.4.p':'Doctor issues an electronic prescription online, with detailed medication instructions and follow-up advice',
    'zx.ps.5.p':'Authentic Japanese medications shipped internationally from a licensed pharmacy, delivered safely and compliantly',
    'zx.who.1.p':'Feeling unwell during a trip or business stay in Japan? No need to navigate hospitals — get a Japanese doctor\'s diagnosis from your phone.',
    'zx.who.2.p':'Living abroad but trusting Japanese healthcare quality — needing advice from a Japanese specialist or authentic Japanese prescription medications.',
    'zx.who.3.p':'Too busy to visit a hospital — wanting convenient medical care available at home or in the office, anytime.',
    'zx.who.4.p':'Needing continuous chronic disease management or long-term medication — easily obtain repeat prescriptions through online follow-up visits.',
    'zx.faq.1.a':'Yes. All participating doctors hold a 医師免許 (medical licence) issued by Japan\'s Ministry of Health, Labour and Welfare and have undergone complete clinical training in their specialties. The platform is operated by a compliant Japanese medical institution, regulated by Japanese medical law. You can review the doctor\'s licence information before your consultation.',
    'zx.faq.2.a':'We currently deliver to mainland China, Hong Kong, Taiwan, Singapore, Malaysia, Australia, and other major regions. Specific medications available vary by destination import regulations — we will advise during your consultation. Note that certain controlled substances may not be internationally mailable, and the doctor will provide alternatives in those cases.',
    'zx.faq.3.a':'Consultation fees vary by specialty and duration, generally ranging from CNY 300–800. Prescription medication fees and shipping are charged separately and disclosed before your consultation. First-time bookings through Sakura Medical enjoy an exclusive discount — contact our consultants for a quote.',
    'zx.faq.4.a':'Online consultation is suitable for chronic disease management, common illness consultations, repeat prescriptions, AGA hair loss, weight management, skin issues, and other non-emergency needs. For emergencies (severe chest pain, breathing difficulty, serious trauma, etc.) or conditions requiring physical examination or surgery, please visit your local hospital emergency department immediately.',
    'zx.faq.5.a':'Consultations are available in Chinese (Mandarin / Cantonese), Japanese, and English. Most patients communicate directly and fluently with doctors in Chinese without a translator. All consultation records, prescription instructions, and medication guidance can be provided in Chinese.',
