    'svc.3.t':'재생의료','svc.3.d':'일본 선도적인 줄기세포·PRP 재생요법으로 신체 자가치유 능력을 활성화하여 관절 재생, 항노화, 아건강 개선에 활용합니다.','svc.3.link':'자세히 보기 →',
