    /* --- WHY --- */
    'why.tag':'저희의 강점','why.title':'전 세계 고객이<br>사쿠라를 신뢰하는 이유',
    'why.desc':'10년 이상 일본 의료 자원을 깊이 개척해 온 저희는 단순한 에이전시가 아니라 일본에서의 전담 의료 컨시어지입니다. 예약부터 귀국 후 추적 관리까지 모든 단계를 전문가가 동행합니다.',
    'why.f1.t':'최상위 병원 직접 연계','why.f1.d':'도쿄대학 부속병원 등 50개 이상 최고 의료기관과 계약 체결, 우선 예약으로 대기 없이 진료 가능합니다.',
    'why.f2.t':'1:多 전담 컨시어지 팀','why.f2.d':'전담 의료 상담사·통역사·생활 어시스턴트 3인 팀이 전 과정을 서포트하여 타지에서도 안심하실 수 있습니다.',
