    'testi.tag':'고객 후기','testi.title':'사쿠라를 선택하고 인생이 바뀌었습니다',
    'testi.1.t':'"사쿠라의 주선으로 도쿄에서 눈 성형 수술을 받았습니다. 의사의 실력이 기대 이상이었고, 전 과정을 통역사가 동행해 언어 장벽이 전혀 없었습니다. 귀국 후에도 지속적으로 관리해 주셔서 정말 만족합니다!"',
    'testi.1.name':'임 여사','testi.1.meta':'싱가포르 · 미용성형',
    'testi.2.t':'"아버지의 폐 이상이 조기 발견되어 사쿠라를 통해 도쿄대학 부속병원 PET-CT 정밀검진을 예약했습니다. 확진 후 즉시 치료 방침이 정해졌고, 사쿠라 팀의 전문적이고 신속한 대응이 큰 힘이 되었습니다."',
    'testi.2.name':'진 씨','testi.2.meta':'말레이시아 · 정밀건강검진',
    'testi.3.t':'"재생의료 중 줄기세포 치료를 받았고, 관절 통증이 눈에 띄게 개선되었습니다. 사쿠라는 예약부터 귀국 후 추적 관리까지 담당자가 배정되어 완전히 신뢰할 수 있습니다."',
