    'mm.in.tag':'왜 일본 미용성형인가','mm.in.title':'엄격한 기준이 만드는<br>세계 최고 수준의 미용성형 기술',
    'mm.in.lead':'일본 미용성형은 "자연스러움, 정교함, 안전성"으로 세계에 알려져 있습니다. 모든 성형외과 의사는 7년간의 외과 수련을 완료하고 일본 성형외과학회 전문의 자격을 취득해야만 독립적으로 수술을 집도할 수 있습니다.',
    'mm.in.p1':'일본 후생노동성은 전 세계에서 가장 엄격한 의료기관 감독 기준을 적용하며, 수술 재료, 장비 및 운영 규범은 모두 PMDA(약품·의료기기국) 인증을 받아야 합니다. 즉, 일본에서 받는 모든 수술은 국가 차원의 품질 보장을 받습니다.',
    'mm.in.p2':'사쿠라 메디컬은 긴자, 오모테산도 등 최고급 상권의 권위 있는 병원과 깊이 협력하며, 가장 적합한 전문의를 매칭하고 전 과정을 한국어로 동행합니다.',
    'mm.it.tag':'서비스 항목','mm.it.title':'6대 핵심 미용성형 시술','mm.it.sub':'모든 시술은 일본 전문의가 주도하며 안면 골격과 피부 특성에 맞게 맞춤 설계됩니다',
    'mm.adv.tag':'일본 미용성형의 강점','mm.adv.title':'왜 일본 성형 기술이 세계를 선도하는가','mm.adv.sub':'기술뿐만 아니라, 완벽한 의료 문화와 품질 체계',
