    'why.tag':'Ưu thế của chúng tôi','why.title':'Tại sao khách hàng toàn cầu<br>tin tưởng Sakura Medical',
    'why.desc':'Hơn 10 năm gắn bó sâu với y tế Nhật Bản — chúng tôi không chỉ là trung gian, mà là người quản lý y tế riêng của bạn tại Nhật Bản. Mỗi bước đều có chuyên gia đồng hành.',
    'why.f1.t':'Kết nối trực tiếp bệnh viện hàng đầu','why.f1.d':'Hợp tác với hơn 50 cơ sở y tế hàng đầu gồm Bệnh viện Đại học Tokyo — đặt lịch ưu tiên, không chờ đợi.',
    'why.f2.t':'Đội ngũ quản lý cá nhân','why.f2.d':'Chuyên viên tư vấn y tế, phiên dịch và trợ lý cuộc sống — đội 3 người phục vụ toàn trình, an tâm tuyệt đối.',
    'why.f3.t':'Báo giá minh bạch','why.f3.d':'Tất cả dịch vụ niêm yết rõ ràng. Bảng chi tiết chi phí cung cấp trước khi ký hợp đồng, không có phí ẩn.',
    'why.f4.t':'Theo dõi sau khi về nước','why.f4.d':'6–12 tháng theo dõi song ngữ sau khi về nước, duy trì liên lạc với bác sĩ điều trị tại Nhật.',
    'why.card.t':'Cam kết chất lượng Sakura','why.card.d':'Tất cả bác sĩ đối tác đều có chứng chỉ chuyên khoa Nhật Bản, bệnh viện được JCQHC công nhận.',
