    'testi.tag':'Khách hàng nói gì','testi.title':'Họ chọn Sakura và thay đổi cuộc đời',
    'testi.1.t':'"Sakura sắp xếp phẫu thuật mắt tại Tokyo cho tôi. Tay nghề bác sĩ vượt kỳ vọng. Phiên dịch song ngữ toàn trình giúp tôi không gặp rào cản ngôn ngữ, và được theo dõi tiếp tục sau khi về. Rất đáng giới thiệu!"',
    'testi.1.name':'Chị Lâm','testi.1.meta':'Singapore · Thẩm mỹ phẫu thuật',
    'testi.2.t':'"Bố tôi phát hiện vấn đề phổi sớm. Qua Sakura, chúng tôi đặt lịch PET-CT tại Bệnh viện Đại học Tokyo. Phác đồ điều trị được lập ngay sau chẩn đoán. Sự chuyên nghiệp của đội Sakura là chỗ dựa lớn cho gia đình tôi."',
    'testi.2.name':'Anh Trần','testi.2.meta':'Malaysia · Khám sức khỏe chuyên sâu',
    'testi.3.t':'"Đau khớp của tôi cải thiện rõ rệt sau liệu pháp tế bào gốc. Dịch vụ của Sakura rất chu đáo — từ đặt lịch đến theo dõi sau điều trị đều có người phụ trách. Hoàn toàn đáng tin cậy."',
    'testi.3.name':'Anh Vương','testi.3.meta':'Bangkok, Thái Lan · Y học tái sinh',
