    'tj.cmp.r8.k':'Chăm sóc theo dõi','tj.cmp.r8.jp':'Lời khuyên sức khỏe dài hạn cá nhân hóa','tj.cmp.r8.cn':'Thường không có theo dõi',
    'tj.it.tag':'6 Cấp độ xét nghiệm','tj.it.title':'Quét sức khỏe toàn thân hệ thống & Toàn diện','tj.it.sub':'Từ chỉ số cơ bản đến hình ảnh tiên tiến — 6 cấp độ xây dựng hồ sơ sức khỏe hoàn chỉnh',
    'tj.it.1.t':'Khám thực thể toàn diện','tj.it.2.t':'Xét nghiệm sinh hóa','tj.it.3.t':'Bộ chỉ dấu khối u đầy đủ','tj.it.4.t':'Hình ảnh tiên tiến','tj.it.5.t':'Kiểm tra tim mạch & Não','tj.it.6.t':'Chuyên gia giải thích báo cáo',
    'tj.it.1.d':'Bác sĩ nội khoa giàu kinh nghiệm thực hiện khám thực thể hệ thống, đánh giá dấu hiệu khối u bề mặt và chức năng các cơ quan, xây dựng hồ sơ sức khỏe cơ bản.',
    'tj.it.2.d':'Xét nghiệm toàn diện chức năng gan, thận, đường huyết, mỡ máu, tuyến giáp và hơn 170 chỉ số sinh hóa để đánh giá chính xác trạng thái trao đổi chất và chức năng các cơ quan.',
    'tj.it.3.d':'Bộ 21 chỉ dấu khối u — hơn 3 lần so với khám thông thường — cải thiện đáng kể độ nhạy phát hiện sớm ung thư đại trực tràng, phổi và phụ khoa.',
    'tj.it.4.d':'MRI cao từ trường, CT đa lớp cắt, siêu âm độ phân giải cao và nội soi tiêu hóa cho hình ảnh chính xác não, ngực bụng và vùng chậu, phát hiện tổn thương nhỏ.',
    'tj.it.5.d':'PET-CT là công nghệ tầm soát khối u toàn thân tiên tiến nhất hiện nay, theo dõi hoạt động trao đổi chất của tế bào ung thư để phát hiện nhiều ung thư ác tính giai đoạn sớm trong một lần chụp.',
    'tj.it.6.d':'Tất cả kết quả được bác sĩ chuyên khoa Nhật Bản đọc toàn diện kèm báo cáo dịch tiếng Việt và lời khuyên quản lý sức khỏe cá nhân hóa.',
    'tj.it.1.t1':'Khám thị giác & Sờ nắn','tj.it.1.t2':'Kiểm tra hạch','tj.it.1.t3':'Đánh giá bề mặt',
